CREATE TABLE site_operations(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES members,source_message_id text NOT NULL,idempotency_key text NOT NULL,proposal jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,run_id,idempotency_key),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
ALTER TABLE inventory_movements ADD COLUMN operation_id uuid REFERENCES site_operations DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE inventory_movements ADD COLUMN original_operation_id uuid REFERENCES site_operations DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE unit_conversions(project_id uuid NOT NULL REFERENCES projects,material_id uuid NOT NULL REFERENCES materials,from_unit text NOT NULL,to_unit text NOT NULL,factor numeric NOT NULL CHECK(factor>0),PRIMARY KEY(project_id,material_id,from_unit,to_unit));
CREATE TABLE issues(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,location_id uuid NOT NULL REFERENCES locations,description text NOT NULL,observed_condition text NOT NULL,status text NOT NULL CHECK(status IN ('open','in_review','resolved')),version integer NOT NULL DEFAULT 1,evidence_ids uuid[] NOT NULL,source_message_id text NOT NULL,drawing_reference text NOT NULL DEFAULT 'P-03 revision 3, W2 (demo)',resolution_note text,FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE assignments(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,issue_id uuid NOT NULL REFERENCES issues,assignee_id uuid NOT NULL REFERENCES members,blocking_work_item_id uuid NOT NULL REFERENCES work_items,due_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('pending','in_progress','completed','cancelled')),version integer NOT NULL DEFAULT 1,evidence_ids uuid[] NOT NULL,FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
ALTER TABLE dependencies ADD COLUMN issue_id uuid REFERENCES issues;
CREATE TABLE committed_deliveries(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,material_id uuid NOT NULL REFERENCES materials,quantity numeric NOT NULL CHECK(quantity>=0),due_date date NOT NULL,status text NOT NULL CHECK(status IN ('confirmed','received','cancelled')),reference text NOT NULL,FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE procurement_needs(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,material_id uuid NOT NULL REFERENCES materials,activity_id uuid NOT NULL REFERENCES work_items,required_date date NOT NULL,area numeric NOT NULL,allowance numeric NOT NULL,usable_stock numeric NOT NULL,committed_stock numeric NOT NULL,net_quantity numeric NOT NULL,version integer NOT NULL,evidence_ids uuid[] NOT NULL,UNIQUE(run_id,activity_id,material_id),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE proposal_change_intents(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,operation_id uuid NOT NULL REFERENCES site_operations DEFERRABLE INITIALLY DEFERRED,need_id uuid NOT NULL REFERENCES procurement_needs,need_version integer NOT NULL,reason text NOT NULL,handled_at timestamptz,UNIQUE(operation_id,need_id),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
